# Surah Fatir (chapter 35) — part 5: ayat 41-45 (IDs 3701-3705)
SURAH = 35

ENTRIES = {
3701: (
"بے شک اللہ آسمانوں اور زمین کو سنبھالتا ہے کہ وہ ہٹ نہ جائیں — اور اگر وہ ہٹ جائیں تو اس کے بعد انہیں کوئی سنبھالنے والا نہیں — بے شک وہ حلیم و غفور ہے",
"""۱۔ اللہ کی قدرت — آسمان و زمین کا سنبھالنا؛ اندازہ؛ حلیم و غفور۔
۲۔ ’’إِنَّ اللَّهَ يُمْسِكُ السَّمَاوَاتِ وَالْأَرْضَ أَن تَزُولَا وَلَئِن زَالَتَا إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِّن بَعْدِهِ إِنَّهُ كَانَ حَلِيمًا غَفُورًا‘‘ — بے شک اللہ آسمانوں اور زمین کو سنبھالتا ہے کہ وہ ہٹ نہ جائیں — اور اگر وہ ہٹ جائیں تو اس کے بعد انہیں کوئی سنبھالنے والا نہیں — بے شک وہ حلیم و غفور ہے — یعنی بے شک اللہ آسمانوں اور زمین کو سنبھالتا ہے کہ وہ ہٹ نہ جائیں اور اگر وہ ہٹ جائیں تو اس کے بعد انہیں کوئی سنبھالنے والا نہیں بے شک وہ حلیم و غفور ہے۔
۳۔ عملی سبق: اللہ کی قدرت پر بھروسہ رکھو؛ شکر کرو؛ اللہ سے ڈرو۔"""
),
3702: (
"اور انہوں نے اللہ کی پکی پکی قسمیں کھائیں — اگر ان کے پاس کوئی ڈرانے والا آئے تو وہ کسی امت سے زیادہ ہدایت یافتہ ہوں گے — پھر جب ان کے پاس ڈرانے والا آیا تو اس نے انہیں دوری کے سوا کچھ نہیں بڑھایا",
"""۱۔ کافروں کے وعدے — پکی قسمیں؛ نذیر کا آنا؛ نفور۔
۲۔ ’’وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَانِهِمْ لَئِن جَاءَهُمْ نَذِيرٌ لَّيَكُونُنَّ أَهْدَىٰ مِنْ إِحْدَى الْأُمَمِ فَلَمَّا جَاءَهُمْ نَذِيرٌ مَّا زَادَهُمْ إِلَّا نُفُورًا‘‘ — اور انہوں نے اللہ کی پکی پکی قسمیں کھائیں — اگر ان کے پاس کوئی ڈرانے والا آئے تو وہ کسی امت سے زیادہ ہدایت یافتہ ہوں گے — پھر جب ان کے پاس ڈرانے والا آیا تو اس نے انہیں دوری کے سوا کچھ نہیں بڑھایا — یعنی اور انہوں نے اللہ کی پکی پکی قسمیں کھائیں اگر ان کے پاس کوئی ڈرانے والا آئے تو وہ کسی امت سے زیادہ ہدایت یافتہ ہوں گے پھر جب ان کے پاس ڈرانے والا آیا تو اس نے انہیں دوری کے سوا کچھ نہیں بڑھایا۔
۳۔ عملی سبق: اللہ کے سامنے کیے گئے عہد پورے کرو؛ نذیر ﷺ کو مانو؛ اللہ سے ڈرو۔"""
),
3703: (
"زمین میں تکبر کرنے کے لیے اور بری چال — اور بری چال صرف اپنے اہل کو ہی آ گھیرتی ہے — تو کیا وہ سابقین کی سنت کا انتظار کر رہے ہیں — تو تم اللہ کی سنت میں تبدیلی نہیں پاؤ گے — اور نہ تم اللہ کی سنت میں تبدیلی پاؤ گے",
"""۱۔ تکبر و مکر سیئ — ہلاکت؛ سنتِ اولين؛ تبدیلی نہیں۔
۲۔ ’’اسْتِكْبَارًا فِي الْأَرْضِ وَمَكْرَ السَّيِّئِ وَلَا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلَّا بِأَهْلِهِ فَهَلْ يَنظُرُونَ إِلَّا سُنَّتَ الْأَوَّلِينَ فَلَن تَجِدَ لِسُنَّۃِ اللَّهِ تَبْدِيلًا وَلَن تَجِدَ لِسُنَّۃِ اللَّهِ تَحْوِيلًا‘‘ — زمین میں تکبر کرنے کے لیے اور بری چال — اور بری چال صرف اپنے اہل کو ہی آ گھیرتی ہے — تو کیا وہ سابقین کی سنت کا انتظار کر رہے ہیں — تو تم اللہ کی سنت میں تبدیلی نہیں پاؤ گے — اور نہ تم اللہ کی سنت میں تبدیلی پاؤ گے — یعنی زمین میں تکبر کرنے کے لیے اور بری چال اور بری چال صرف اپنے اہل کو ہی آ گھیرتی ہے تو کیا وہ سابقین کی سنت کا انتظار کر رہے ہیں تو تم اللہ کی سنت میں تبدیلی نہیں پاؤ گے اور نہ تم اللہ کی سنت میں تبدیلی پاؤ گے۔
۳۔ عملی سبق: تکبر و مکر چھوڑو؛ اللہ کی سنت دیکھو؛ اللہ سے ڈرو۔"""
),
3704: (
"کیا وہ زمین میں چلے نہیں پھرتے کہ دیکھیں کیسا انجام تھا ان کا جو ان سے پہلے تھے — اور وہ ان سے زیادہ قوت والے تھے — اور اللہ کو آسمانوں اور زمین میں کوئی چیز عاجز نہیں کر سکتی — بے شک وہ دانا و قادر ہے",
"""۱۔ سیر فی الارض — سابقہ اقوام؛ قوت؛ اللہ کا علم و قدرت؛ عدمِ اعجاز۔
۲۔ ’’أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَۃُ الَّذِينَ مِن قَبْلِهِمْ وَكَانُوا أَشَدَّ مِنْهُمْ قُوَّۃً وَمَا كَانَ اللَّهُ لِيُعْجِزَهُ مِن شَيْءٍ فِي السَّمَاوَاتِ وَلَا فِي الْأَرْضِ إِنَّهُ كَانَ عَلِيمًا قَدِيرًا‘‘ — کیا وہ زمین میں چلے نہیں پھرتے کہ دیکھیں کیسا انجام تھا ان کا جو ان سے پہلے تھے — اور وہ ان سے زیادہ قوت والے تھے — اور اللہ کو آسمانوں اور زمین میں کوئی چیز عاجز نہیں کر سکتی — بے شک وہ دانا و قادر ہے — یعنی کیا وہ زمین میں چلے نہیں پھرتے کہ دیکھیں کیسا انجام تھا ان کا جو ان سے پہلے تھے اور وہ ان سے زیادہ قوت والے تھے اور اللہ کو آسمانوں اور زمین میں کوئی چیز عاجز نہیں کر سکتی بے شک وہ دانا و قادر ہے۔
۳۔ عملی سبق: سابقہ اقوام سے عبرت لو؛ اللہ کی قدرت پر بھروسہ رکھو۔"""
),
3705: (
"اور اگر اللہ لوگوں کو ان کے اعمال کے بدلے پکڑتا تو زمین پر کوئی چلنے والا نہ چھوڑتا — لیکن وہ انہیں ایک مقررہ وقت تک مہلت دیتا ہے — پھر جب ان کا وقت آئے گا تو بے شک اللہ اپنے بندوں کو دیکھنے والا ہے",
"""۱۔ اللہ کا حلم — عدمِ فوری پکڑ؛ اجلِ مسمی؛ فیصلِ علم۔
۲۔ ’’وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِمَا كَسَبُوا مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَابَّۃٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰ أَجَلٍ مُّسَمًّى فَإِذَا جَاءَ أَجَلُهُمْ فَإِنَّ اللَّهَ كَانَ بِعِبَادِهِ بَصِيرًا‘‘ — اور اگر اللہ لوگوں کو ان کے اعمال کے بدلے پکڑتا تو زمین پر کوئی چلنے والا نہ چھوڑتا — لیکن وہ انہیں ایک مقررہ وقت تک مہلت دیتا ہے — پھر جب ان کا وقت آئے گا تو بے شک اللہ اپنے بندوں کو دیکھنے والا ہے — یعنی اور اگر اللہ لوگوں کو ان کے اعمال کے بدلے پکڑتا تو زمین پر کوئی چلنے والا نہ چھوڑتا لیکن وہ انہیں ایک مقررہ وقت تک مہلت دیتا ہے پھر جب ان کا وقت آئے گا تو بے شک اللہ اپنے بندوں کو دیکھنے والا ہے۔
۳۔ عملی سبق: اللہ کی مہلت سے دھوکا نہ کھاؤ؛ توبہ کرو؛ اعمال سنوار لو۔"""
),
}
